// components/Thumbnail.jsx
import React, { useState, useEffect } from 'react';
import './Thumbnail.scss';

function Thumbnail({ src, title = 'blog', alt = 'Post image' }) {
  const [imgSrc, setImgSrc] = useState('');
  const [error, setError] = useState(false);

  // Safe fallback keywords
  const fallbackKeywords = ['technology', 'writing', 'code', 'nature', 'typing', 'notebook'];
  const fallbackPrompt = fallbackKeywords[Math.floor(Math.random() * fallbackKeywords.length)];
  const fallback = `https://source.unsplash.com/800x400/?${fallbackPrompt}`;

  useEffect(() => {
    if (src?.trim()) {
      setImgSrc(src);
    } else {
      setImgSrc(fallback);
    }
  }, [src]);

  return (
    <div className="thumbnail">
      {error ? (
        <div className="thumbnail__placeholder">📷 No image available</div>
      ) : (
        <img
          src={imgSrc}
          alt={alt}
          className="thumbnail__image"
          onError={() => {
            setImgSrc(fallback);
            setError(false); // prevent fallback loop
          }}
        />
      )}
    </div>
  );
}

export default Thumbnail;
